window.ProjectPortfolio=(()=>{
 const statuses=['On Track','At Risk','Overdue','Not Started','Completed'],colors={'On Track':'#1bae7a','At Risk':'#efa823',Overdue:'#f16070','Not Started':'#9db2cc',Completed:'#3388ef'};
 function model(data,today,period='all'){
  const until=period==='all'?null:Planning.iso(Planning.day(today)+Number(period));
  const projects=data.projects.filter(p=>!until||(p.startDate<=until&&p.endDate>=today));
  const rows=projects.map(project=>{const tasks=data.issues.filter(t=>t.projectId===project.id),open=tasks.filter(t=>t.status!=='Done'),done=tasks.length-open.length;
   const status=project.status==='Completed'||tasks.length&&done===tasks.length?'Completed':project.endDate<today?'Overdue':project.status==='On hold'||open.some(t=>t.endDate<today||['High','Critical'].includes(t.priority))?'At Risk':!tasks.length||project.startDate>today?'Not Started':'On Track';
   const priority=['Critical','High','Medium','Low'].find(priority=>open.some(t=>t.priority===priority))||'—';
   return {project,tasks,done,open,status,priority,progress:tasks.length?Math.round(done/tasks.length*100):0};
  });
  const ids=new Set(projects.map(p=>p.id)),tasks=data.issues.filter(t=>ids.has(t.projectId)),memberIds=new Set();
  for(const p of projects){if(p.managerId)memberIds.add(p.managerId);for(const id of p.memberIds||[])memberIds.add(id);for(const id of data.teams.find(t=>t.id===p.teamId)?.memberIds||[])memberIds.add(id)}for(const t of tasks)if(t.assigneeId)memberIds.add(t.assigneeId);
  return {rows,tasks,until,people:data.members.filter(m=>memberIds.has(m.id)),counts:statuses.map(status=>({status,count:rows.filter(r=>r.status===status).length})),phases:[...new Set(tasks.map(t=>t.phase||'Other'))].map(phase=>({phase,total:tasks.filter(t=>(t.phase||'Other')===phase).length,done:tasks.filter(t=>(t.phase||'Other')===phase&&t.status==='Done').length})),milestones:data.milestones.filter(m=>ids.has(m.projectId)&&m.status!=='Completed'&&m.date>=today&&(!until||m.date<=until)).sort((a,b)=>a.date.localeCompare(b.date)),activity:data.activity.filter(a=>ids.has(a.projectId)).slice(0,7)};
 }
 function render(data,{today,date,avatar,period='all',filter='All',query=''}){
  const m=model(data,today,period),percent=count=>m.rows.length?Math.round(count/m.rows.length*100):0,counts=Object.fromEntries(m.counts.map(c=>[c.status,c.count]));
  const filtered=m.rows.filter(r=>(filter==='All'||r.status===filter)&&(r.project.name+' '+ProjectAPI.projectKey(r.project)+' '+(data.members.find(x=>x.id===r.project.managerId)?.name||'')).toLowerCase().includes(query.toLowerCase()));
  let angle=0;const gradient=m.counts.filter(c=>c.count).map(c=>{const before=angle;angle+=c.count/Math.max(1,m.rows.length)*100;return `${colors[c.status]} ${before}% ${angle}%`}).join(',')||'#e3ecf6 0% 100%';
  const statusBars=m.counts.map(c=>`<div class="pf-status-row"><span><i style="background:${colors[c.status]}"></i>${c.status}</span><div class="pf-status-meter"><i style="width:${percent(c.count)}%;background:${colors[c.status]}"></i></div><small>${c.count} · ${percent(c.count)}%</small></div>`).join('');
  return `<div class="pf-heading"><div><h1>Project Portfolio</h1><p>Overview of all projects, their status and key metrics at a glance.</p></div><div class="pf-periods" aria-label="Portfolio schedule window">${[['all','All'],['7','7D'],['30','30D'],['90','3M'],['180','6M'],['365','1Y']].map(([value,label])=>`<button data-pf-period="${value}" aria-pressed="${value===period}">${label}</button>`).join('')}</div></div><p class="pf-window">${m.until?`Projects whose schedules overlap ${date(today)} – ${date(m.until)}`:'All project schedules'} · Current data</p><div class="pf-layout"><div class="pf-main"><section class="pf-kpis">${[['▱','Total Projects',m.rows.length,'Projects in this view','green'],['◉','On Track',counts['On Track'],percent(counts['On Track'])+'% of projects','blue'],['△','At Risk',counts['At Risk'],percent(counts['At Risk'])+'% of projects','orange'],['!','Overdue',counts.Overdue,percent(counts.Overdue)+'% of projects','red'],['♧','Team Members',m.people.length,'Distinct contributors','purple']].map(([icon,label,value,note,color])=>`<article class="panel pf-kpi ${color}"><i>${icon}</i><div><span>${label}</span><strong>${value}</strong><small>${note}</small></div></article>`).join('')}</section><div class="pf-charts"><section class="panel"><h2>Project Status Overview</h2><div class="pf-donut-layout"><div class="pf-donut" style="background:conic-gradient(${gradient})"><span><b>${m.rows.length}</b>Projects</span></div><div class="pf-chart-legend">${m.counts.map(c=>`<div><i style="background:${colors[c.status]}"></i>${c.status}<b>${c.count}</b></div>`).join('')}</div></div></section><section class="panel"><h2>Tasks by Phase</h2><p class="pf-caption">Completed / total tasks</p><div class="pf-phases">${m.phases.map(p=>`<div><span>${esc(p.phase)}</span><div class="pf-phase-track"><i style="width:${p.done/Math.max(1,p.total)*100}%"></i></div><small>${p.done}/${p.total}</small></div>`).join('')||'<p class="pf-empty">No tasks in this view.</p>'}</div><p class="pf-caption">Green: completed · Pale blue: open</p></section><section class="panel"><h2>Project Progress</h2><p class="pf-caption">Current completion by task count</p><div class="pf-progress-list">${m.rows.slice(0,6).map(r=>`<button data-project-dashboard="${esc(r.project.id)}"><span>${esc(r.project.name)}</span><div class="pf-phase-track"><i style="width:${r.progress}%"></i></div><b>${r.progress}%</b></button>`).join('')||'<p class="pf-empty">No projects in this view.</p>'}</div></section></div><section class="panel pf-projects"><div class="pf-table-heading"><h2>Projects</h2><button class="primary" data-action="new-project">+ New project</button></div><div class="pf-table-controls"><div class="pf-filters" aria-label="Filter project health">${['All',...statuses].map(status=>`<button data-pf-status="${status}" aria-pressed="${status===filter}">${status} (${status==='All'?m.rows.length:counts[status]})</button>`).join('')}</div><input id="pf-search" aria-label="Search portfolio projects" placeholder="Search projects or owners…" value="${esc(query)}"></div><div class="bug-table-wrap"><table class="pf-table"><thead><tr><th>Project Name</th><th>Owner</th><th>Status</th><th>Progress</th><th>Start Date</th><th>End Date</th><th title="Highest priority of open tasks">Task Priority</th><th>Actions</th></tr></thead><tbody>${filtered.map(r=>{const p=r.project,owner=data.members.find(x=>x.id===p.managerId);return `<tr><td><button class="pf-project-link" data-project-dashboard="${esc(p.id)}"><i>▱</i><span>${esc(p.name)}<small>${esc(ProjectAPI.projectKey(p))}</small></span></button></td><td><div class="pf-owner">${avatar(owner)}<span>${esc(owner?.name||'Unassigned')}</span></div></td><td><span class="pf-status-pill" style="--status:${colors[r.status]}">● ${r.status}</span></td><td><div class="pf-progress-cell"><div class="pf-phase-track"><i style="width:${r.progress}%"></i></div>${r.progress}%</div></td><td>${esc(p.startDate)}</td><td>${esc(p.endDate)}</td><td>${r.priority}</td><td><button class="text-btn" data-project-edit="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">Edit</button></td></tr>`}).join('')||'<tr><td colspan="8">No projects match these filters.</td></tr>'}</tbody></table></div><p class="pf-caption">Health: completed first; then past-due projects; then on-hold projects or open overdue/high-priority tasks. Task Priority is the highest open-task priority.</p></section></div><div class="pf-right"><section class="panel"><h2>Project Status</h2>${statusBars}</section><section class="panel"><h2>Upcoming Milestones</h2><div class="pf-milestones">${m.milestones.slice(0,7).map(item=>`<button data-milestone-edit="${esc(item.id)}"><time>${date(item.date)}</time><span><strong>${esc(item.name)}</strong><small>${esc(data.projects.find(p=>p.id===item.projectId)?.name||'')}</small></span></button>`).join('')||'<p class="pf-empty">No upcoming milestones in this view.</p>'}</div></section><section class="panel"><h2>Recent Activity</h2><div class="pf-activity">${m.activity.map(a=>`<div><span class="pf-actor">${esc((a.actor||'Local').slice(0,2).toUpperCase())}</span><div><strong>${esc(a.actor||'Local')}</strong><p>${esc(a.summary||a.name||'')}</p><small>${esc(a.time||new Date(a.createdAt).toLocaleString())}</small></div></div>`).join('')||'<p class="pf-empty">No recent activity for these projects.</p>'}</div></section></div></div>`;
 }
 return {model,render};
})();
